-- Read-only validation; EXCEPT ALL verifies row-level multiset preservation.
BEGIN TRANSACTION READ ONLY;
WITH base_minus_view AS (SELECT f."year", f."month", f."day", f."day_of_week", f."airline", f."flight_number", f."tail_number", f."origin_airport", f."destination_airport", f."scheduled_departure", f."departure_time", f."departure_delay", f."taxi_out", f."wheels_off", f."scheduled_time", f."elapsed_time", f."air_time", f."distance", f."wheels_on", f."taxi_in", f."scheduled_arrival", f."arrival_time", f."arrival_delay", f."diverted", f."cancelled", f."cancellation_reason", f."air_system_delay", f."security_delay", f."airline_delay", f."late_aircraft_delay", f."weather_delay" FROM public.flights f EXCEPT ALL SELECT v."year", v."month", v."day", v."day_of_week", v."airline", v."flight_number", v."tail_number", v."origin_airport", v."destination_airport", v."scheduled_departure", v."departure_time", v."departure_delay", v."taxi_out", v."wheels_off", v."scheduled_time", v."elapsed_time", v."air_time", v."distance", v."wheels_on", v."taxi_in", v."scheduled_arrival", v."arrival_time", v."arrival_delay", v."diverted", v."cancelled", v."cancellation_reason", v."air_system_delay", v."security_delay", v."airline_delay", v."late_aircraft_delay", v."weather_delay" FROM public.flights_normalized v),
view_minus_base AS (SELECT v."year", v."month", v."day", v."day_of_week", v."airline", v."flight_number", v."tail_number", v."origin_airport", v."destination_airport", v."scheduled_departure", v."departure_time", v."departure_delay", v."taxi_out", v."wheels_off", v."scheduled_time", v."elapsed_time", v."air_time", v."distance", v."wheels_on", v."taxi_in", v."scheduled_arrival", v."arrival_time", v."arrival_delay", v."diverted", v."cancelled", v."cancellation_reason", v."air_system_delay", v."security_delay", v."airline_delay", v."late_aircraft_delay", v."weather_delay" FROM public.flights_normalized v EXCEPT ALL SELECT f."year", f."month", f."day", f."day_of_week", f."airline", f."flight_number", f."tail_number", f."origin_airport", f."destination_airport", f."scheduled_departure", f."departure_time", f."departure_delay", f."taxi_out", f."wheels_off", f."scheduled_time", f."elapsed_time", f."air_time", f."distance", f."wheels_on", f."taxi_in", f."scheduled_arrival", f."arrival_time", f."arrival_delay", f."diverted", f."cancelled", f."cancellation_reason", f."air_system_delay", f."security_delay", f."airline_delay", f."late_aircraft_delay", f."weather_delay" FROM public.flights f),
tests(test_name,actual,expected,passed) AS (
 SELECT 'crosswalk_rows',COUNT(*)::TEXT,'307',COUNT(*)=307 FROM public.airport_id_iata_crosswalk WHERE source_dataset_month=DATE '2015-10-01'
 UNION ALL SELECT 'unique_crosswalk_keys',COUNT(*)::TEXT,'0 duplicate keys',COUNT(*)=0 FROM (SELECT source_dataset_month,airport_id FROM public.airport_id_iata_crosswalk GROUP BY source_dataset_month,airport_id HAVING COUNT(*)>1) q
 UNION ALL SELECT 'null_crosswalk_fields',COUNT(*)::TEXT,'0',COUNT(*)=0 FROM public.airport_id_iata_crosswalk WHERE source_dataset_month=DATE '2015-10-01' AND (source_dataset_month IS NULL OR airport_id IS NULL OR airport_sequence_id IS NULL OR iata_code IS NULL OR source_identifier_system IS NULL OR source_file IS NULL OR source_dataset_file IS NULL OR source_url IS NULL OR source_sha256 IS NULL OR source_download_date IS NULL)
 UNION ALL SELECT 'conflicting_ID_to_code_or_sequence',COUNT(*)::TEXT,'0',COUNT(*)=0 FROM (SELECT airport_id FROM public.airport_id_iata_crosswalk WHERE source_dataset_month=DATE '2015-10-01' GROUP BY airport_id HAVING COUNT(DISTINCT iata_code)>1 OR COUNT(DISTINCT airport_sequence_id)>1) q
 UNION ALL SELECT 'codes_missing_from_airports_reference',COUNT(*)::TEXT,'0',COUNT(*)=0 FROM public.airport_id_iata_crosswalk c LEFT JOIN public.airports a ON a.iata_code=c.iata_code WHERE c.source_dataset_month=DATE '2015-10-01' AND a.iata_code IS NULL
 UNION ALL SELECT 'base_flight_rows',COUNT(*)::TEXT,'5819079',COUNT(*)=5819079 FROM public.flights
 UNION ALL SELECT 'base_october_rows',COUNT(*)::TEXT,'486165',COUNT(*)=486165 FROM public.flights WHERE year=2015 AND month=10
 UNION ALL SELECT 'normalized_view_rows',COUNT(*)::TEXT,'5819079',COUNT(*)=5819079 FROM public.flights_normalized
 UNION ALL SELECT 'base_rows_missing_from_view',COUNT(*)::TEXT,'0',COUNT(*)=0 FROM base_minus_view
 UNION ALL SELECT 'extra_or_multiplied_view_rows',COUNT(*)::TEXT,'0',COUNT(*)=0 FROM view_minus_base
 UNION ALL SELECT 'October_origin_endpoint_coverage',COUNT(*) FILTER(WHERE r.iata_code IS NOT NULL AND v.origin_airport_iata=r.iata_code)::TEXT,'486165',COUNT(*) FILTER(WHERE r.iata_code IS NOT NULL AND v.origin_airport_iata=r.iata_code)=486165 FROM public.flights_normalized v LEFT JOIN public.airports r ON r.iata_code=v.origin_airport_iata WHERE v.year=2015 AND v.month=10
 UNION ALL SELECT 'October_destination_endpoint_coverage',COUNT(*) FILTER(WHERE r.iata_code IS NOT NULL AND v.destination_airport_iata=r.iata_code)::TEXT,'486165',COUNT(*) FILTER(WHERE r.iata_code IS NOT NULL AND v.destination_airport_iata=r.iata_code)=486165 FROM public.flights_normalized v LEFT JOIN public.airports r ON r.iata_code=v.destination_airport_iata WHERE v.year=2015 AND v.month=10
 UNION ALL SELECT 'October_both_endpoint_airport_join_rows',COUNT(*)::TEXT,'486165',COUNT(*)=486165 FROM public.flights_normalized v JOIN public.airports o ON o.iata_code=v.origin_airport_iata JOIN public.airports d ON d.iata_code=v.destination_airport_iata WHERE v.year=2015 AND v.month=10
 UNION ALL SELECT 'October_unresolved_numeric_endpoints',COUNT(*)::TEXT,'0',COUNT(*)=0 FROM public.flights_normalized v WHERE v.year=2015 AND v.month=10 AND ((v.origin_airport ~ '^[0-9]+$' AND v.origin_airport_mapping_status='unresolved') OR (v.destination_airport ~ '^[0-9]+$' AND v.destination_airport_mapping_status='unresolved'))
 UNION ALL SELECT 'destination_ID_10666_maps_to_BLI',COUNT(*)::TEXT,'1',COUNT(*)=1 FROM public.flights_normalized WHERE year=2015 AND month=10 AND destination_airport='10666' AND destination_airport_iata='BLI' AND destination_airport_mapping_status='mapped_from_dot_id'
 UNION ALL SELECT 'non_October_airport_values_changed',COUNT(*)::TEXT,'0',COUNT(*)=0 FROM public.flights_normalized WHERE (year IS DISTINCT FROM 2015 OR month IS DISTINCT FROM 10) AND (origin_airport_iata IS DISTINCT FROM origin_airport OR destination_airport_iata IS DISTINCT FROM destination_airport)
 UNION ALL SELECT 'October_existing_alphabetic_origins_changed',COUNT(*)::TEXT,'0',COUNT(*)=0 FROM public.flights_normalized WHERE year=2015 AND month=10 AND origin_airport !~ '^[0-9]+$' AND origin_airport_iata IS DISTINCT FROM origin_airport
 UNION ALL SELECT 'October_existing_alphabetic_destinations_changed',COUNT(*)::TEXT,'0',COUNT(*)=0 FROM public.flights_normalized WHERE year=2015 AND month=10 AND destination_airport !~ '^[0-9]+$' AND destination_airport_iata IS DISTINCT FROM destination_airport
 UNION ALL SELECT 'crosswalk_scope_other_months',COUNT(*)::TEXT,'0',COUNT(*)=0 FROM public.airport_id_iata_crosswalk WHERE source_dataset_month<>DATE '2015-10-01'
 UNION ALL SELECT 'mapping_applied_outside_October',COUNT(*)::TEXT,'0',COUNT(*)=0 FROM public.flights_normalized WHERE (year IS DISTINCT FROM 2015 OR month IS DISTINCT FROM 10) AND (origin_airport_mapping_status='mapped_from_dot_id' OR destination_airport_mapping_status='mapped_from_dot_id')
)
SELECT test_name,actual,expected,CASE WHEN passed THEN 'PASS' ELSE 'FAIL' END AS result FROM tests ORDER BY test_name;
ROLLBACK;
